function dictListToRows(dictList) {
  if (!Array.isArray(dictList) || dictList.length === 0) return [];

  const keys = [...new Set(dictList.flatMap(obj => Object.keys(obj)))];

  return dictList.map(obj => {
    const row = {};
    keys.forEach(key => {
      row[key] = obj.hasOwnProperty(key) ? obj[key] : null;
    });
    return row;
  });
}

